let debugStep = "0 - Start";
let weeklySummaryTable;

function setOutputSafe(name, value) {
  try {
    output.set(name, value);
  } catch {
    // Ignore unmapped output keys.
  }
}

function step(name) {
  debugStep = name;
  setOutputSafe("debugStep", debugStep);
}

function fieldExists(table, name) {
  try {
    table.getField(name);
    return true;
  } catch {
    return false;
  }
}

function getRaw(record, table, name) {
  return record && fieldExists(table, name) ? record.getCellValue(name) : null;
}

function getText(record, table, name) {
  return record && fieldExists(table, name) ? String(record.getCellValueAsString(name) || "").trim() : "";
}

function linkedIds(record, table, name) {
  const value = getRaw(record, table, name);
  return Array.isArray(value) ? value.map((x) => x?.id).filter(Boolean) : [];
}

function getNumber(record, table, name, fallback = 0) {
  const value = getRaw(record, table, name);
  const parsed =
    typeof value === "number"
      ? value
      : Number(
          String(value ?? "")
            .replace(/[$,%]/g, "")
            .replace(/,/g, "")
            .trim()
        );
  return Number.isFinite(parsed) ? parsed : fallback;
}

function nullableNumber(record, table, name) {
  const value = getRaw(record, table, name);
  if (value === null || value === undefined || value === "") return null;
  const parsed =
    typeof value === "number"
      ? value
      : Number(
          String(value)
            .replace(/[$,%]/g, "")
            .replace(/,/g, "")
            .trim()
        );
  return Number.isFinite(parsed) ? parsed : null;
}

function booleanish(record, table, name) {
  const value = getRaw(record, table, name);
  if (value === true || value === 1) return true;
  if (value === false || value === 0) return false;
  return ["1", "true", "yes", "checked", "y", "count", "counted"].includes(
    getText(record, table, name).toLowerCase()
  );
}

function oneLinkedId(ids, label) {
  if (ids.length !== 1) throw new Error(`${label} must have exactly one link; found ${ids.length}.`);
  return ids[0];
}

function sameIds(a, b) {
  return a.length === b.length && a.every((x) => b.includes(x));
}

function firstNonEmpty(...values) {
  return values.map((x) => String(x ?? "").trim()).find(Boolean) || "";
}

function emailsJoined(value) {
  return [...new Set(String(value || "").split(/[,;\n]+/).map((s) => s.trim().toLowerCase()).filter(Boolean))].join(",");
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function formatDate(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (!value || Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", {
    timeZone: CONFIG.timeZone,
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(date);
}

function toDateKey(value) {
  if (!value) return "";
  if (typeof value === "string") {
    const trimmed = String(value).trim();
    const isoMatch = trimmed.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
    const localMatch = trimmed.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
    if (localMatch) {
      return `${localMatch[3]}-${localMatch[1].padStart(2, "0")}-${localMatch[2].padStart(2, "0")}`;
    }
  }
  const dateValue = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(dateValue.getTime())) return "";
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: CONFIG.timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(dateValue);
  const year = parts.find((p) => p.type === "year")?.value || "";
  const month = parts.find((p) => p.type === "month")?.value || "";
  const day = parts.find((p) => p.type === "day")?.value || "";
  if (!year || !month || !day) return "";
  return `${year}-${month}-${day}`;
}

function toSafeDateKey(rawValue, textValue) {
  const fromRaw = toDateKey(rawValue);
  if (fromRaw) return fromRaw;
  return toDateKey(textValue);
}

function isDateKeyInWeekRange(dateKey, startKey, endKey) {
  if (!dateKey || !startKey || !endKey) return true;
  return dateKey >= startKey && dateKey <= endKey;
}

function goalCompletionPercentFromRatio(ratio) {
  const raw = Number(ratio);
  if (!Number.isFinite(raw)) return null;
  return Math.round(raw * 100);
}

function goalCompletionRatioFromShotsAndGoal(shots, goal, ratioFromWas) {
  const weeklyShots = Number(shots || 0);
  const weeklyGoal = Number(goal || 0);
  if (weeklyGoal > 0) return weeklyShots / weeklyGoal;
  const raw = Number(ratioFromWas);
  if (!Number.isFinite(raw)) return null;
  return raw;
}

function goalCompletionPercentFromShotsAndGoal(shots, goal, ratioFromWas) {
  const ratio = goalCompletionRatioFromShotsAndGoal(shots, goal, ratioFromWas);
  return ratio == null ? null : goalCompletionPercentFromRatio(ratio);
}

function formatGoalCompletionDisplayForEmail(ratio) {
  const raw = Number(ratio);
  if (!Number.isFinite(raw)) return "—";
  if (raw + 1e-9 >= 1.5) return "150%+";
  if (raw + 1e-9 >= 1.25) return "125%";
  if (raw + 1e-9 >= 1.0) return "100%";
  return `${Math.round(raw * 100)}%`;
}

function isSafeHttpUrl(url) {
  try {
    const parsed = new URL(String(url || "").trim());
    return parsed.protocol === "http:" || parsed.protocol === "https:";
  } catch {
    return false;
  }
}

const LAMBDA_VIEWER_HOST_RE = /\.lambda-url\.us-east-2\.on\.aws$/i;
const RECORD_ID_RE = /^rec[a-zA-Z0-9]{14}$/;
const FILE_PATH_RE = /^\/file\/(rec[a-zA-Z0-9]{14})\/?$/;
const S3_HOST_RE =
  /(?:^|\.)s3[.-][a-z0-9-]+\.amazonaws\.com$|\.s3\.amazonaws\.com$|\.s3\.[a-z0-9-]+\.amazonaws\.com$|shooting-challenge-assets/i;
const GOOGLE_DRIVE_HOST_RE = /^(?:drive|docs)\.google\.com$/i;
const PRESIGNED_QUERY_RE = /(?:^|[?&])(?:X-Amz-|AWSAccessKeyId=|Signature=)/i;

function classifySecureVideoUrl(url) {
  const raw = String(url || "").trim();
  if (!raw) return { classification: "missing_reviewer_url", safeUrl: "" };
  let parsed;
  try {
    parsed = new URL(raw);
  } catch {
    return { classification: "malformed_url", safeUrl: "" };
  }
  if (parsed.protocol !== "https:") return { classification: "malformed_url", safeUrl: "" };
  if (GOOGLE_DRIVE_HOST_RE.test(parsed.hostname)) {
    return { classification: "google_drive_rejected", safeUrl: "" };
  }
  if (S3_HOST_RE.test(parsed.hostname) || S3_HOST_RE.test(raw)) {
    if (PRESIGNED_QUERY_RE.test(parsed.search) || PRESIGNED_QUERY_RE.test(raw)) {
      return { classification: "presigned_s3_rejected", safeUrl: "" };
    }
    return { classification: "direct_s3_rejected", safeUrl: "" };
  }
  if (PRESIGNED_QUERY_RE.test(parsed.search)) {
    return { classification: "presigned_s3_rejected", safeUrl: "" };
  }
  if (LAMBDA_VIEWER_HOST_RE.test(parsed.hostname)) {
    const pathMatch = parsed.pathname.match(FILE_PATH_RE);
    if (!pathMatch || !RECORD_ID_RE.test(pathMatch[1])) {
      return { classification: "malformed_url", safeUrl: "" };
    }
    const token = String(parsed.searchParams.get("token") || "").trim();
    if (!token) return { classification: "missing_token", safeUrl: "" };
    return { classification: "valid_lambda_viewer", safeUrl: raw };
  }
  return { classification: "invalid_host", safeUrl: "" };
}

function isValidLambdaViewerUrl(url) {
  return classifySecureVideoUrl(url).classification === "valid_lambda_viewer";
}

function linkedIdsInclude(record, table, name, targetId) {
  return linkedIds(record, table, name).includes(targetId);
}

function videoFeedbackMatchesWeek(vf, vfTable, weekId, weekSubmissionIdSet) {
  if (linkedIdsInclude(vf, vfTable, CONFIG.videoFeedback.week, weekId)) return true;
  const subIds = linkedIds(vf, vfTable, CONFIG.videoFeedback.submission);
  return subIds.some((sid) => weekSubmissionIdSet.has(sid));
}

function formatShootingPercentage(makes, shots) {
  const m = Number(makes || 0);
  const s = Number(shots || 0);
  if (s <= 0) return 0;
  return Math.round((m / s) * 100);
}

function buildVideoSubmissionLines(entries) {
  if (!entries.length) return ["No video submissions recorded for this week."];
  return entries.map((entry) => {
    const label = String(entry.label || entry.originalFileName || "Video submission").trim();
    const reviewedAt = String(entry.reviewedAt || "").trim();
    const secureUrl = isValidLambdaViewerUrl(entry.secureUrl) ? String(entry.secureUrl).trim() : "";
    const datePart = reviewedAt ? ` (${reviewedAt})` : "";
    const urlPart = secureUrl ? ` — ${secureUrl}` : "";
    return `${label}${datePart}${urlPart}`;
  });
}

function buildZoomAttendanceSummary(zoom) {
  const status = String(zoom.status || "").trim();
  if (status) return status;
  const meetings = Number(zoom.meetingCount || 0);
  if (meetings === 0) return "No Zoom This Week";
  if (zoom.requirementMet === true) return "Attended";
  if (Number(zoom.attendanceCount || 0) >= 1) return "Attended";
  return "Missed";
}

function inclusiveWeekDayCount(weekStartKey, weekEndKey) {
  if (!weekStartKey || !weekEndKey || weekEndKey < weekStartKey) return null;
  const [sy, sm, sd] = weekStartKey.split("-").map(Number);
  const [ey, em, ed] = weekEndKey.split("-").map(Number);
  const start = Date.UTC(sy, sm - 1, sd);
  const end = Date.UTC(ey, em - 1, ed);
  return Math.round((end - start) / 86400000) + 1;
}

function parsePerfectWeekDailyDetail(detail) {
  const text = String(detail || "");
  const result = { dailyMinimum: null, passingOfficialDays: null, requiredDays: null };
  const weekMatch = text.match(/Official week:\s*(\d{4}-\d{2}-\d{2})\s+through\s+(\d{4}-\d{2}-\d{2})/i);
  if (weekMatch) result.requiredDays = inclusiveWeekDayCount(weekMatch[1], weekMatch[2]);
  const dailyMinMatch = text.match(/Daily minimum:\s*(\d+)/i);
  if (dailyMinMatch) result.dailyMinimum = Number(dailyMinMatch[1]);
  const passingMatch = text.match(/Passing official days:\s*(\d+)\/(\d+)/i);
  if (passingMatch) {
    result.passingOfficialDays = Number(passingMatch[1]);
    result.requiredDays = Number(passingMatch[2]);
  }
  return result;
}

function formatDaysLoggedAgainstCriteria(logged, required) {
  const count = Number(logged || 0);
  if (required == null || !Number.isFinite(Number(required)) || Number(required) <= 0) return String(count);
  return `${count}/${Number(required)}`;
}

function formatVideoProgress(count, required, requirementMet) {
  const n = Number(count || 0);
  if (required != null && Number.isFinite(Number(required)) && Number(required) > 0) return `${n}/${Number(required)}`;
  if (requirementMet === true) return `${n} (requirement met)`;
  if (requirementMet === false) return `${n} (requirement not met)`;
  return String(n);
}

function buildPerfectWeekEmailCriteria(input) {
  const parsed = parsePerfectWeekDailyDetail(input.dailyDetail);
  const requiredShootingDays =
    input.achievementRequiredDays ??
    parsed.requiredDays ??
    (input.weekStartKey && input.weekEndKey
      ? inclusiveWeekDayCount(input.weekStartKey, input.weekEndKey)
      : null);
  const weeklyGoal = Number(input.weeklyGoalShots || 0);
  const dailyShootingMinimum =
    parsed.dailyMinimum ??
    (weeklyGoal > 0 && requiredShootingDays
      ? Math.ceil(weeklyGoal / requiredShootingDays)
      : null);
  const daysLogged = Number(input.daysLogged ?? parsed.passingOfficialDays ?? 0);
  const shootingDaysLogged =
    input.shootingDaysLogged != null ? Number(input.shootingDaysLogged) : null;
  const videoCount = Number(input.videoCount || 0);
  const videoRequirementMet =
    input.videoRequirementMet === true ||
    input.videoRequirementMet === 1 ||
    input.videoRequirementMet === "1";
  const zoomRequirementStatus = String(input.zoomRequirementStatus || "").trim();
  return {
    requiredShootingDays,
    dailyShootingMinimum,
    shootingDaysLogged,
    shootingDaysDisplay:
      shootingDaysLogged != null
        ? formatDaysLoggedAgainstCriteria(shootingDaysLogged, requiredShootingDays)
        : null,
    daysLogged,
    daysLoggedDisplay: formatDaysLoggedAgainstCriteria(daysLogged, requiredShootingDays),
    perfectWeekQualifyingDaysDisplay: formatDaysLoggedAgainstCriteria(daysLogged, requiredShootingDays),
    videoCount,
    videoRequired: input.videoRequired ?? null,
    videoRequirementMet,
    videoProgressDisplay: formatVideoProgress(
      videoCount,
      input.videoRequired ?? null,
      videoRequirementMet
    ),
    zoomMeetingCount: Number(input.zoomMeetingCount || 0),
    zoomAttendanceCount: Number(input.zoomAttendanceCount || 0),
    zoomRequirementStatus,
    zoomRequirementMet:
      input.zoomRequirementMet === true ||
      input.zoomRequirementMet === 1 ||
      input.zoomRequirementMet === "1" ||
      zoomRequirementStatus === "Attended" ||
      zoomRequirementStatus === "No Zoom This Week",
    homeworkRequirementStatus: String(input.homeworkRequirementStatus || "").trim(),
    homeworkRequirementMet:
      input.homeworkRequirementMet === true ||
      input.homeworkRequirementMet === 1 ||
      input.homeworkRequirementMet === "1",
    eligible: input.eligible === true || input.eligible === 1 || input.eligible === "1",
    perfectWeekXpAmount:
      input.achievementXpAmount == null ? null : Number(input.achievementXpAmount),
  };
}

function formatNumber(value) {
  const n = Number(value || 0);
  return Number.isFinite(n) ? Math.round(n).toLocaleString("en-US") : "0";
}

function normalizeSlot(value) {
  const s = String(value || "")
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "");
  if (["HW1", "HOMEWORK1"].includes(s)) return "HW1";
  if (["HW2", "HOMEWORK2"].includes(s)) return "HW2";
  return s;
}

async function loadQuery(table, names) {
  return await table.selectRecordsAsync({ fields: names.filter((n) => fieldExists(table, n)) });
}

function normalizeMode(value) {
  const s = String(value || "")
    .trim()
    .toLowerCase();
  if (["live", "l", "real", "send", "parent"].includes(s)) return "live";
  if (["test", "t", "preview", "practice", "draft"].includes(s)) return "test";
  return "";
}

function normalizeEmptyWeekPolicy(value) {
  const s = String(value || "")
    .trim()
    .toLowerCase();
  return ["send_short", "send_normal", "suppress"].includes(s) ? s : "send_short";
}

function listHtml(items) {
  return items.length ? `<ul>${items.map((x) => `<li>${escapeHtml(x)}</li>`).join("")}</ul>` : "<p>None</p>";
}

function fullHtml(data) {
  const goalCompletion =
    data.goalCompletionDisplay ||
    (data.goalCompletionPercent != null ? `${formatNumber(data.goalCompletionPercent)}%` : "—");
  const shootingPct =
    data.shootingPercentage != null ? `${formatNumber(data.shootingPercentage)}%` : "—";
  const shootingDaysLine = escapeHtml(
    data.shootingDaysDisplay ||
      (data.shootingDaysLogged != null ? formatNumber(data.shootingDaysLogged) : "—")
  );
  const perfectWeekDaysLine = escapeHtml(
    data.perfectWeekDaysDisplay ||
      data.perfectWeekQualifyingDaysDisplay ||
      data.daysLoggedDisplay ||
      formatNumber(data.perfectWeekDaysLogged || data.days)
  );
  return `<!doctype html><html><body style="margin:0;background:#F2F2F2;font-family:Arial,sans-serif;color:#262626"><div style="max-width:700px;margin:auto;background:#fff"><div style="background:#0034B7;color:#fff;padding:22px;border-bottom:6px solid #FF8B00"><h2 style="margin:0">Weekly Shooting Challenge Summary</h2><p style="margin:6px 0 0">${escapeHtml(data.weekLabel)}</p></div><div style="padding:22px"><p>Hi ${escapeHtml(data.firstName || data.athleteName)}, here is your weekly progress.</p><h3>Shooting</h3><p>Shooting Days Logged: <strong>${shootingDaysLine}</strong><br>Shots: <strong>${formatNumber(data.shots)}</strong><br>Makes: <strong>${formatNumber(data.makes)}</strong><br>Shooting %: <strong>${shootingPct}</strong><br>Weekly Goal: <strong>${data.goal ? formatNumber(data.goal) : "—"}</strong><br>Goal Completion: <strong>${goalCompletion}</strong></p><h3>Perfect Week Progress</h3><p>Perfect Week Qualifying Days: <strong>${perfectWeekDaysLine}</strong><br>Daily minimum: <strong>${data.perfectWeekDailyMinimum != null ? formatNumber(data.perfectWeekDailyMinimum) : "—"}</strong><br>Videos: <strong>${escapeHtml(data.perfectWeekVideoProgress || "—")}</strong><br>Zoom: <strong>${escapeHtml(data.zoomSummary)}</strong><br>Homework: <strong>${escapeHtml(data.perfectWeekHomeworkStatus || "—")}</strong><br>Eligible: <strong>${data.perfectWeekEligible ? "Yes" : "No"}</strong>${data.perfectWeekXpAmount != null ? `<br>Perfect Week XP: <strong>${formatNumber(data.perfectWeekXpAmount)}</strong>` : ""}</p><h3>Video Submissions</h3>${listHtml(data.videoLines)}<h3>Homework Assigned</h3>${listHtml(data.assignments)}<h3>Homework Progress</h3>${listHtml(data.homework)}<h3>XP Earned</h3><p><strong>${formatNumber(data.weekXp)} XP</strong></p>${listHtml(data.xpLines)}<h3>Progression</h3><p>Current Level: <strong>${escapeHtml(data.level || "Not yet assigned")}</strong><br>Current Streak: <strong>${formatNumber(data.streak)} days</strong>${data.streakStatus ? `<br>Streak Status: <strong>${escapeHtml(data.streakStatus)}</strong>` : ""}</p></div></div></body></html>`;
}

function shortHtml(data) {
  return `<!doctype html><html><body style="margin:0;background:#F2F2F2;font-family:Arial,sans-serif;color:#262626"><div style="max-width:650px;margin:auto;background:#fff"><div style="background:#0034B7;color:#fff;padding:22px;border-bottom:6px solid #FF8B00"><h2 style="margin:0">Shooting Challenge Weekly Reminder</h2></div><div style="padding:22px"><p>Hi ${escapeHtml(data.firstName || data.athleteName)}, no countable shooting activity was recorded for ${escapeHtml(data.weekLabel)}.</p><p>Start a new week by getting one session logged and keep building consistency.</p></div></div></body></html>`;
}

function plainText(data, short) {
  if (short) {
    return `Shooting Challenge Weekly Reminder\n${data.weekLabel}\n\nNo countable shooting activity was recorded this week.`;
  }
  return `Weekly Shooting Challenge Summary\n${data.weekLabel}\nAthlete: ${data.athleteName}\nShooting Days Logged: ${data.shootingDaysDisplay || (data.shootingDaysLogged != null ? data.shootingDaysLogged : "—")}\nPerfect Week Qualifying Days: ${data.perfectWeekDaysDisplay || data.perfectWeekQualifyingDaysDisplay || data.daysLoggedDisplay || data.perfectWeekDaysLogged || data.days}\nShots: ${data.shots}\nMakes: ${data.makes}\nShooting %: ${data.shootingPercentage}\nWeekly Goal: ${data.goal}\nGoal Completion: ${data.goalCompletionDisplay || data.goalCompletionPercent}\nPerfect Week Videos: ${data.perfectWeekVideoProgress}\nPerfect Week Zoom: ${data.zoomSummary}\nPerfect Week Homework: ${data.perfectWeekHomeworkStatus}\nVideo: ${data.videoLines.join(" | ")}\nWeekly XP: ${data.weekXp}\nHomework: ${data.homework.join(" | ")}\nXP: ${data.xpLines.join(" | ")}`;
}

async function skipBuild(recordId, action, message) {
  if (fieldExists(weeklySummaryTable, CONFIG.was.buildNow)) {
    await weeklySummaryTable.updateRecordAsync(recordId, { [CONFIG.was.buildNow]: false });
  }
  setOutputSafe("statusOut", CONFIG.statuses.skipped);
  setOutputSafe("actionOut", action);
  setOutputSafe("errorOut", message);
  setOutputSafe("debugStep", debugStep);
}

async function suppressEmptyWeek(recordId, message) {
  const updates = {};
  if (fieldExists(weeklySummaryTable, CONFIG.was.buildNow)) updates[CONFIG.was.buildNow] = false;
  if (fieldExists(weeklySummaryTable, CONFIG.was.ready)) updates[CONFIG.was.ready] = false;
  if (fieldExists(weeklySummaryTable, CONFIG.was.send)) updates[CONFIG.was.send] = false;
  if (fieldExists(weeklySummaryTable, CONFIG.was.error)) updates[CONFIG.was.error] = message;
  await weeklySummaryTable.updateRecordAsync(recordId, updates);
  setOutputSafe("statusOut", CONFIG.statuses.skipped);
  setOutputSafe("actionOut", CONFIG.actions.suppressedEmptyWeek);
  setOutputSafe("errorOut", message);
  setOutputSafe("debugStep", debugStep);
}

/* =========================================================
   SECTION 4: MAIN
========================================================= */

async function main() {
  step("1 - Validate inputs");
  const cfg = typeof input !== "undefined" && input?.config ? input.config() : {};
  const recordId = String(cfg.recordId || "").trim();
  const allowSchmidt = String(cfg.allowSchmidtInput || "").trim().toLowerCase() === "true";
  const emptyWeekPolicy = normalizeEmptyWeekPolicy(cfg.emptyWeekPolicy);
  const inputMode = normalizeMode(cfg.sendModeInput || cfg.sendMode);
  if (!recordId) throw new Error("Missing required input: recordId");

  step("2 - Load tables and summary");
  weeklySummaryTable = base.getTable(CONFIG.tables.weeklySummary);
  const enrollmentsTable = base.getTable(CONFIG.tables.enrollments);
  const weeksTable = base.getTable(CONFIG.tables.weeks);
  const submissionsTable = base.getTable(CONFIG.tables.submissions);
  const homeworkCompletionsTable = base.getTable(CONFIG.tables.homeworkCompletions);
  const xpEventsTable = base.getTable(CONFIG.tables.xpEvents);
  const phaTable = base.getTable(CONFIG.tables.pha);
  const homeworkLibraryTable = base.getTable(CONFIG.tables.homeworkLibrary);

  const summary = await weeklySummaryTable.selectRecordAsync(recordId);
  if (!summary) throw new Error(`Weekly Athlete Summary not found: ${recordId}`);

  const enrollmentId = oneLinkedId(linkedIds(summary, weeklySummaryTable, CONFIG.was.enrollment), "WAS Enrollment");
  const weekId = oneLinkedId(linkedIds(summary, weeklySummaryTable, CONFIG.was.week), "WAS Week");
  const enrollment = await enrollmentsTable.selectRecordAsync(enrollmentId);
  const week = await weeksTable.selectRecordAsync(weekId);
  if (!enrollment || !week) throw new Error("WAS source Enrollment/Week not found.");

  step("3 - Gate inactive / Schmidt / already sent");
  if (fieldExists(enrollmentsTable, CONFIG.enrollments.active) && !booleanish(enrollment, enrollmentsTable, CONFIG.enrollments.active)) {
    await skipBuild(recordId, CONFIG.actions.skippedInactive, "Enrollment inactive.");
    return;
  }
  if (enrollmentId === CONFIG.schmidtEnrollmentId && !allowSchmidt) {
    await skipBuild(recordId, CONFIG.actions.skippedSchmidt, "Schmidt test enrollment excluded unless allowSchmidtInput=true.");
    return;
  }
  if (fieldExists(weeklySummaryTable, CONFIG.was.sent) && booleanish(summary, weeklySummaryTable, CONFIG.was.sent)) {
    await skipBuild(recordId, CONFIG.actions.skippedAlreadySent, "Weekly Email Sent? already checked.");
    return;
  }

  const programId = oneLinkedId(
    linkedIds(enrollment, enrollmentsTable, CONFIG.enrollments.programInstance),
    "Enrollment Program Instance"
  );
  const gradeId = oneLinkedId(
    linkedIds(enrollment, enrollmentsTable, CONFIG.enrollments.gradeBand),
    "Enrollment Grade Band"
  );

  step("4 - Canonical countable submissions / shots");
  const weekStartKey = toSafeDateKey(
    getRaw(week, weeksTable, CONFIG.weeks.start),
    getText(week, weeksTable, CONFIG.weeks.start)
  );
  const weekEndKey = toSafeDateKey(
    getRaw(week, weeksTable, CONFIG.weeks.end),
    getText(week, weeksTable, CONFIG.weeks.end)
  );
  const submissionQuery = await loadQuery(submissionsTable, [
    CONFIG.submissions.enrollment,
    CONFIG.submissions.week,
    CONFIG.submissions.countThis,
    CONFIG.submissions.shots,
    CONFIG.submissions.makes,
    CONFIG.submissions.activityDate,
    CONFIG.submissions.perfectWeekCountable,
  ]);
  const linkedSubmissionIds = linkedIds(summary, weeklySummaryTable, CONFIG.was.submissions);
  const countableSubs = [];
  for (const sid of linkedSubmissionIds) {
    const submission = submissionQuery.getRecord(sid);
    if (!submission) throw new Error(`WAS linked Submission not found: ${sid}`);
    if (
      !sameIds(linkedIds(submission, submissionsTable, CONFIG.submissions.enrollment), [enrollmentId]) ||
      !sameIds(linkedIds(submission, submissionsTable, CONFIG.submissions.week), [weekId])
    ) {
      throw new Error(`WAS Submission ${sid} owned by another Enrollment/Week.`);
    }
    if (!booleanish(submission, submissionsTable, CONFIG.submissions.countThis)) continue;
    const activityDateKey = toSafeDateKey(
      getRaw(submission, submissionsTable, CONFIG.submissions.activityDate),
      getText(submission, submissionsTable, CONFIG.submissions.activityDate)
    );
    if (!activityDateKey) {
      throw new Error(`Countable submission ${sid} is missing a valid Activity Date.`);
    }
    if (!isDateKeyInWeekRange(activityDateKey, weekStartKey, weekEndKey)) continue;
    countableSubs.push(submission);
  }
  const shootingDayKeys = new Set(
    countableSubs.map((s) =>
      toSafeDateKey(
        getRaw(s, submissionsTable, CONFIG.submissions.activityDate),
        getText(s, submissionsTable, CONFIG.submissions.activityDate)
      )
    )
  );
  const perfectWeekDayKeys = new Set();
  for (const sid of linkedSubmissionIds) {
    const submission = submissionQuery.getRecord(sid);
    if (!submission) continue;
    if (
      !sameIds(linkedIds(submission, submissionsTable, CONFIG.submissions.enrollment), [enrollmentId]) ||
      !sameIds(linkedIds(submission, submissionsTable, CONFIG.submissions.week), [weekId])
    ) {
      continue;
    }
    if (!booleanish(submission, submissionsTable, CONFIG.submissions.perfectWeekCountable)) continue;
    const activityDateKey = toSafeDateKey(
      getRaw(submission, submissionsTable, CONFIG.submissions.activityDate),
      getText(submission, submissionsTable, CONFIG.submissions.activityDate)
    );
    if (!activityDateKey || !isDateKeyInWeekRange(activityDateKey, weekStartKey, weekEndKey)) continue;
    perfectWeekDayKeys.add(activityDateKey);
  }
  const shootingDaysLogged = shootingDayKeys.size;
  const perfectWeekDaysLogged = perfectWeekDayKeys.size;
  const scannedShots = countableSubs.reduce(
    (sum, s) => sum + getNumber(s, submissionsTable, CONFIG.submissions.shots),
    0
  );
  const scannedMakes = countableSubs.reduce(
    (sum, s) => sum + getNumber(s, submissionsTable, CONFIG.submissions.makes),
    0
  );
  const summaryShots = nullableNumber(summary, weeklySummaryTable, CONFIG.was.shots);
  const summaryMakes = nullableNumber(summary, weeklySummaryTable, CONFIG.was.makes);
  const summaryDays = nullableNumber(summary, weeklySummaryTable, CONFIG.was.daysLogged);
  if (summaryShots !== null && Math.abs(summaryShots - scannedShots) > 0.001) {
    throw new Error(`Weekly shots disagreement: summary=${summaryShots}, canonical submissions=${scannedShots}.`);
  }
  if (summaryMakes !== null && Math.abs(summaryMakes - scannedMakes) > 0.001) {
    throw new Error(`Weekly makes disagreement: summary=${summaryMakes}, canonical submissions=${scannedMakes}.`);
  }
  const shots = scannedShots;
  const makes = scannedMakes;

  step("5 - Active XP Events only");
  const xpQuery = await loadQuery(xpEventsTable, [
    CONFIG.xpEvents.active,
    CONFIG.xpEvents.points,
    CONFIG.xpEvents.enrollment,
    CONFIG.xpEvents.week,
    CONFIG.xpEvents.submission,
    CONFIG.xpEvents.homeworkCompletion,
    CONFIG.xpEvents.videoFeedback,
    CONFIG.xpEvents.unlock,
    CONFIG.xpEvents.source,
    CONFIG.xpEvents.bucket,
    CONFIG.xpEvents.reason,
    CONFIG.xpEvents.sourceKey,
  ]);
  const wasLinkedXpIds = linkedIds(summary, weeklySummaryTable, CONFIG.was.xpEvents);
  const activeXpAll = xpQuery.records.filter(
    (x) =>
      booleanish(x, xpEventsTable, CONFIG.xpEvents.active) &&
      sameIds(linkedIds(x, xpEventsTable, CONFIG.xpEvents.enrollment), [enrollmentId]) &&
      sameIds(linkedIds(x, xpEventsTable, CONFIG.xpEvents.week), [weekId])
  );
  const wasLinkedXpIdSet = new Set(wasLinkedXpIds);
  const activeXp = activeXpAll.filter((x) => wasLinkedXpIdSet.has(x.id));
  const orphanXp = activeXpAll.filter((x) => !wasLinkedXpIdSet.has(x.id));
  for (const xid of wasLinkedXpIds) {
    const xpEvent = xpQuery.getRecord(xid);
    if (!xpEvent) throw new Error(`WAS linked XP Event missing: ${xid}`);
    if (
      booleanish(xpEvent, xpEventsTable, CONFIG.xpEvents.active) &&
      (!sameIds(linkedIds(xpEvent, xpEventsTable, CONFIG.xpEvents.enrollment), [enrollmentId]) ||
        !sameIds(linkedIds(xpEvent, xpEventsTable, CONFIG.xpEvents.week), [weekId]))
    ) {
      throw new Error(`WAS active XP Event ${xid} belongs to another Enrollment/Week.`);
    }
  }
  if (orphanXp.length) {
    const orphanPoints = orphanXp.reduce(
      (sum, x) => sum + getNumber(x, xpEventsTable, CONFIG.xpEvents.points),
      0
    );
    throw new Error(
      `Unlinked canonical XP: ${orphanXp.length} active XP Event(s) (+${orphanPoints} XP) match Enrollment+Week but are not linked on this Weekly Athlete Summary. Reconcile WAS XP links before building email.`
    );
  }
  const weekXp = activeXp.reduce((sum, x) => sum + getNumber(x, xpEventsTable, CONFIG.xpEvents.points), 0);
  const summaryXp = nullableNumber(summary, weeklySummaryTable, CONFIG.was.weeklyXp);
  if (summaryXp !== null && Math.abs(summaryXp - weekXp) > 0.001) {
    throw new Error(
      `Weekly XP disagreement: summary rollup=${summaryXp}, WAS-linked active XP=${weekXp}. Wait for rollup settlement or reconcile XP links.`
    );
  }
  const xpLines = activeXp.length
    ? activeXp.map(
        (x) =>
          `${firstNonEmpty(
            getText(x, xpEventsTable, CONFIG.xpEvents.reason),
            getText(x, xpEventsTable, CONFIG.xpEvents.source),
            getText(x, xpEventsTable, CONFIG.xpEvents.bucket),
            "XP"
          )}: ${formatNumber(getNumber(x, xpEventsTable, CONFIG.xpEvents.points))} XP`
      )
    : ["No active XP Events awarded for this week yet."];

  step("6 - Homework schedule (PHA first)");
  const phaQuery = await loadQuery(phaTable, [
    CONFIG.pha.homework,
    CONFIG.pha.programInstance,
    CONFIG.pha.week,
    CONFIG.pha.gradeBand,
    CONFIG.pha.slot,
    CONFIG.pha.active,
  ]);
  const phaRows = phaQuery.records.filter(
    (x) =>
      booleanish(x, phaTable, CONFIG.pha.active) &&
      sameIds(linkedIds(x, phaTable, CONFIG.pha.programInstance), [programId]) &&
      sameIds(linkedIds(x, phaTable, CONFIG.pha.week), [weekId]) &&
      sameIds(linkedIds(x, phaTable, CONFIG.pha.gradeBand), [gradeId])
  );

  let assignmentSource = "PHA";
  let assignments = [];
  if (phaRows.length) {
    for (const pha of phaRows.sort((a, b) =>
      normalizeSlot(getText(a, phaTable, CONFIG.pha.slot)).localeCompare(
        normalizeSlot(getText(b, phaTable, CONFIG.pha.slot))
      )
    )) {
      if (linkedIds(pha, phaTable, CONFIG.pha.homework).length !== 1) {
        throw new Error(`PHA ${pha.id} must link exactly one Homework Assignment.`);
      }
      assignments.push(
        `${normalizeSlot(getText(pha, phaTable, CONFIG.pha.slot)) || "Homework"}: ${getText(pha, phaTable, CONFIG.pha.homework)}`
      );
    }
  } else {
    assignmentSource = "LEGACY_CURRICULUM_NO_PHA";
    const libraryQuery = await loadQuery(homeworkLibraryTable, [
      CONFIG.homeworkLibrary.title,
      CONFIG.homeworkLibrary.full,
      CONFIG.homeworkLibrary.week,
      CONFIG.homeworkLibrary.gradeBand,
      CONFIG.homeworkLibrary.active,
      CONFIG.homeworkLibrary.published,
      CONFIG.homeworkLibrary.order,
    ]);
    assignments = libraryQuery.records
      .filter(
        (x) =>
          sameIds(linkedIds(x, homeworkLibraryTable, CONFIG.homeworkLibrary.week), [weekId]) &&
          (!fieldExists(homeworkLibraryTable, CONFIG.homeworkLibrary.active) ||
            booleanish(x, homeworkLibraryTable, CONFIG.homeworkLibrary.active)) &&
          (!fieldExists(homeworkLibraryTable, CONFIG.homeworkLibrary.published) ||
            booleanish(x, homeworkLibraryTable, CONFIG.homeworkLibrary.published)) &&
          (linkedIds(x, homeworkLibraryTable, CONFIG.homeworkLibrary.gradeBand).length === 0 ||
            linkedIds(x, homeworkLibraryTable, CONFIG.homeworkLibrary.gradeBand).includes(gradeId))
      )
      .sort(
        (a, b) =>
          getNumber(a, homeworkLibraryTable, CONFIG.homeworkLibrary.order, 9999) -
          getNumber(b, homeworkLibraryTable, CONFIG.homeworkLibrary.order, 9999)
      )
      .slice(0, 2)
      .map(
        (x, i) =>
          `HW${i + 1}: ${firstNonEmpty(
            getText(x, homeworkLibraryTable, CONFIG.homeworkLibrary.title),
            getText(x, homeworkLibraryTable, CONFIG.homeworkLibrary.full),
            x.name
          )}`
      );
  }
  if (!assignments.length) assignments = ["No scheduled homework found."];

  step("7 - Homework completion lines");
  const hcQuery = await loadQuery(homeworkCompletionsTable, [
    CONFIG.homeworkCompletions.enrollment,
    CONFIG.homeworkCompletions.week,
    CONFIG.homeworkCompletions.homework,
    CONFIG.homeworkCompletions.slot,
    CONFIG.homeworkCompletions.pha,
    CONFIG.homeworkCompletions.satisfactory,
    CONFIG.homeworkCompletions.status,
    CONFIG.homeworkCompletions.coach,
    CONFIG.homeworkCompletions.xpEvents,
    CONFIG.homeworkCompletions.xpTotal,
    CONFIG.homeworkCompletions.award,
  ]);
  const homework = [];
  for (const hid of linkedIds(summary, weeklySummaryTable, CONFIG.was.homeworkCompletions)) {
    const hc = hcQuery.getRecord(hid);
    if (!hc) throw new Error(`WAS linked Homework Completion not found: ${hid}`);
    if (
      !sameIds(linkedIds(hc, homeworkCompletionsTable, CONFIG.homeworkCompletions.enrollment), [enrollmentId]) ||
      !sameIds(linkedIds(hc, homeworkCompletionsTable, CONFIG.homeworkCompletions.week), [weekId])
    ) {
      throw new Error(`Homework Completion ${hid} belongs to another Enrollment/Week.`);
    }
    if (phaRows.length) {
      const phaIds = linkedIds(hc, homeworkCompletionsTable, CONFIG.homeworkCompletions.pha);
      if (phaIds.length !== 1 || !phaRows.some((p) => p.id === phaIds[0])) {
        throw new Error(`Homework Completion ${hid} is not linked to the current PHA schedule.`);
      }
    }
    const earned = linkedIds(hc, homeworkCompletionsTable, CONFIG.homeworkCompletions.xpEvents)
      .map((id) => xpQuery.getRecord(id))
      .filter(
        (x) =>
          x &&
          booleanish(x, xpEventsTable, CONFIG.xpEvents.active) &&
          sameIds(linkedIds(x, xpEventsTable, CONFIG.xpEvents.enrollment), [enrollmentId]) &&
          sameIds(linkedIds(x, xpEventsTable, CONFIG.xpEvents.week), [weekId])
      )
      .reduce((sum, x) => sum + getNumber(x, xpEventsTable, CONFIG.xpEvents.points), 0);
    homework.push(
      `${firstNonEmpty(
        getText(hc, homeworkCompletionsTable, CONFIG.homeworkCompletions.homework),
        normalizeSlot(getText(hc, homeworkCompletionsTable, CONFIG.homeworkCompletions.slot)),
        "Homework"
      )}: ${booleanish(hc, homeworkCompletionsTable, CONFIG.homeworkCompletions.satisfactory) ? "Satisfactory" : "Pending review"}; XP ${earned > 0 ? formatNumber(earned) + " awarded" : "pending / not awarded"}`
    );
  }
  if (!homework.length) homework.push("No homework completion has been recorded for this week.");

  step("7b - Video feedback rows for week");
  const weekSubmissionIdSet = new Set(linkedSubmissionIds);
  const videoFeedbackTable = base.getTable(CONFIG.tables.videoFeedback);
  const vfQuery = await loadQuery(videoFeedbackTable, [
    CONFIG.videoFeedback.enrollment,
    CONFIG.videoFeedback.week,
    CONFIG.videoFeedback.submission,
    CONFIG.videoFeedback.active,
    CONFIG.videoFeedback.posted,
    CONFIG.videoFeedback.sent,
    CONFIG.videoFeedback.name,
    CONFIG.videoFeedback.originalFileName,
    CONFIG.videoFeedback.videoUrl,
    CONFIG.videoFeedback.reviewedAt,
    CONFIG.videoFeedback.uploadStatus,
    CONFIG.videoFeedback.coach,
  ]);
  const videoSubmissionsRaw = vfQuery.records
    .filter(
      (vf) =>
        booleanish(vf, videoFeedbackTable, CONFIG.videoFeedback.active) &&
        linkedIdsInclude(vf, videoFeedbackTable, CONFIG.videoFeedback.enrollment, enrollmentId) &&
        videoFeedbackMatchesWeek(vf, videoFeedbackTable, weekId, weekSubmissionIdSet)
    )
    .map((vf) => {
      const secureUrlRaw = getText(vf, videoFeedbackTable, CONFIG.videoFeedback.videoUrl);
      const secureUrl = isValidLambdaViewerUrl(secureUrlRaw) ? secureUrlRaw : "";
      return {
        label: firstNonEmpty(
          getText(vf, videoFeedbackTable, CONFIG.videoFeedback.name),
          getText(vf, videoFeedbackTable, CONFIG.videoFeedback.originalFileName),
          "Video submission"
        ),
        originalFileName: getText(vf, videoFeedbackTable, CONFIG.videoFeedback.originalFileName),
        reviewedAt: formatDate(getRaw(vf, videoFeedbackTable, CONFIG.videoFeedback.reviewedAt)),
        secureUrl,
        hadUnsafeOrMissingUrl: Boolean(secureUrlRaw) && !secureUrl,
      };
    });
  const missingSecureUrlCount = videoSubmissionsRaw.filter((row) => row.hadUnsafeOrMissingUrl).length;
  const videoSubmissions = videoSubmissionsRaw.map(({ hadUnsafeOrMissingUrl, ...entry }) => entry);
  const videoLines = buildVideoSubmissionLines(videoSubmissions);

  step("7c - Perfect Week criteria from Achievements, XP Reward Rules, and WAS");
  let achievementRequiredDays = null;
  let achievementXpAmount = null;
  try {
    const achievementsTable = base.getTable(CONFIG.tables.achievements);
    const achievementQuery = await loadQuery(achievementsTable, [
      CONFIG.achievements.active,
      CONFIG.achievements.rewardRuleKey,
      CONFIG.achievements.triggerThreshold,
      CONFIG.achievements.name,
    ]);
    const pwAchievements = achievementQuery.records.filter(
      (row) =>
        booleanish(row, achievementsTable, CONFIG.achievements.active) &&
        getText(row, achievementsTable, CONFIG.achievements.rewardRuleKey) === CONFIG.values.perfectWeekRuleKey
    );
    if (pwAchievements.length === 1) {
      achievementRequiredDays = nullableNumber(
        pwAchievements[0],
        achievementsTable,
        CONFIG.achievements.triggerThreshold
      );
    }
  } catch {
    // Achievements table is optional for package build; WAS fields remain authoritative.
  }
  try {
    const xpRulesTable = base.getTable(CONFIG.tables.xpRewardRules);
    const xpRuleQuery = await loadQuery(xpRulesTable, [
      CONFIG.xpRewardRules.active,
      CONFIG.xpRewardRules.ruleKey,
      CONFIG.xpRewardRules.xpAmount,
      CONFIG.xpRewardRules.gradeBand,
    ]);
    const matchingRules = xpRuleQuery.records.filter((row) => {
      if (!booleanish(row, xpRulesTable, CONFIG.xpRewardRules.active)) return false;
      if (getText(row, xpRulesTable, CONFIG.xpRewardRules.ruleKey) !== CONFIG.values.perfectWeekRuleKey) {
        return false;
      }
      const bands = linkedIds(row, xpRulesTable, CONFIG.xpRewardRules.gradeBand);
      return bands.length === 0 || bands.includes(gradeId);
    });
    if (matchingRules.length === 1) {
      achievementXpAmount = nullableNumber(matchingRules[0], xpRulesTable, CONFIG.xpRewardRules.xpAmount);
    }
  } catch {
    // XP Reward Rules lookup is optional; eligibility still comes from WAS.
  }

  const pwDailyDetail = getText(summary, weeklySummaryTable, CONFIG.was.pwDailyDetail);
  const weeklyGoalShots = getNumber(summary, weeklySummaryTable, CONFIG.was.goal);
  const pwVideoCount = getNumber(summary, weeklySummaryTable, CONFIG.was.pwVideoCount);
  const pwVideoRequirementMet = fieldExists(weeklySummaryTable, CONFIG.was.pwVideoRequirementMet)
    ? getNumber(summary, weeklySummaryTable, CONFIG.was.pwVideoRequirementMet)
    : null;
  const perfectWeekCriteria = buildPerfectWeekEmailCriteria({
    weekStartKey,
    weekEndKey,
    weeklyGoalShots,
    dailyDetail: pwDailyDetail,
    daysLogged: perfectWeekDaysLogged,
    shootingDaysLogged,
    achievementRequiredDays,
    achievementXpAmount,
    videoCount: pwVideoCount,
    videoRequirementMet: pwVideoRequirementMet,
    zoomMeetingCount: nullableNumber(summary, weeklySummaryTable, CONFIG.was.zoomMeetingCount),
    zoomAttendanceCount: nullableNumber(summary, weeklySummaryTable, CONFIG.was.zoomAttendanceCount),
    zoomRequirementStatus: getText(summary, weeklySummaryTable, CONFIG.was.zoomRequirementStatus),
    zoomRequirementMet: fieldExists(weeklySummaryTable, CONFIG.was.zoomRequirementMet)
      ? booleanish(summary, weeklySummaryTable, CONFIG.was.zoomRequirementMet)
      : null,
    homeworkRequirementStatus: getText(summary, weeklySummaryTable, CONFIG.was.pwHomeworkRequirementStatus),
    homeworkRequirementMet: fieldExists(weeklySummaryTable, CONFIG.was.pwHomeworkRequirementMet)
      ? getNumber(summary, weeklySummaryTable, CONFIG.was.pwHomeworkRequirementMet)
      : null,
    eligible: fieldExists(weeklySummaryTable, CONFIG.was.pwEligible)
