  }

  const short = isEmpty && emptyWeekPolicy === "send_short";
  const subject = short
    ? `Shooting Challenge Weekly Reminder - ${athleteName} - ${weekLabel}`
    : `Weekly Shooting Challenge Summary - ${athleteName} - ${weekLabel}`;
  const packageData = {
