/* =========================================================
   SECTION 1 — CONFIGURATION
========================================================= */

const CONFIG = {
  scriptName: "022 - Submission Intake - Sync Child Upload Writeback from Submission Asset",
  version: "v2.2",

  tables: {
    assets: "Submission Assets",
    homework: "Homework Completions",
