function getFirstLinkedId(record, fieldName) {
  const value = record.getCellValue(fieldName);
  if (!Array.isArray(value) || value.length === 0) return null;
  return value[0].id;
}

function getExactlyOneLinkedId(record, fieldName, label) {
  const values = uniqueArray(getLinkedIds(record, fieldName));
  if (values.length !== 1) {
    throw new Error(`${label} must have exactly one linked record; found ${values.length}.`);
  }
  return values[0];
}

function getLinkedIds(record, fieldName) {
  const value = record.getCellValue(fieldName);
  if (!Array.isArray(value)) return [];
  return value.map((item) => item.id);
}

function getLinkedNames(record, fieldName) {
  const value = record.getCellValue(fieldName);
  if (!Array.isArray(value)) return [];
  return value.map((item) => item.name || item.id);
}

function uniqueArray(values) {
  return [...new Set(values.filter(Boolean))];
}

function getNumber(record, fieldName) {
  const value = record.getCellValue(fieldName);

  if (typeof value === "number") return value;

  if (Array.isArray(value) && value.length > 0) {
    const first = value[0];
    if (typeof first === "number") return first;
    const parsed = Number(first);
    return Number.isFinite(parsed) ? parsed : 0;
  }

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function getOptionalNumber(record, fieldName) {
  const value = record.getCellValue(fieldName);
  if (value === null || value === undefined || value === "") return null;
  if (Array.isArray(value)) {
    if (value.length !== 1) return null;
    const first = value[0];
    if (first === null || first === undefined || first === "") return null;
    const parsed = typeof first === "number" ? first : Number(first);
    return Number.isFinite(parsed) ? parsed : null;
  }
  const parsed = typeof value === "number" ? value : Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function getText(record, fieldName) {
  try {
    const v = record.getCellValueAsString(fieldName);
    return v == null ? "" : String(v).trim();
  } catch (e) {
    return "";
  }
}

function isTruthyFlag(record, fieldName) {
  const v = record.getCellValue(fieldName);
  if (v === true || v === 1 || v === "1") return true;
  if (Array.isArray(v) && v.length === 1) {
    const first = v[0];
    return first === true || first === 1 || first === "1";
  }
  return false;
}

function fieldExists(table, name) {
