      console.log(
        "Query unloadData skipped/failed (non-fatal)",
        JSON.stringify({
          error: error instanceof Error ? error.message : String(error),
        })
      );
    }
  }
}

function getDateKeyFromDateOnly(value) {
  if (!value) return "";

  // Preserve true date-only values. Datetime values must be converted through
  // the configured local timezone; Fillout evening submissions arrive as UTC
  // timestamps and their ISO prefix can represent the following calendar day.
  if (typeof value === "string") {
    const trimmed = String(value).trim();
    const isoMatch = trimmed.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
    const localMatch = trimmed.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
    if (localMatch) {
      return `${localMatch[3]}-${localMatch[1].padStart(2, "0")}-${localMatch[2].padStart(2, "0")}`;
    }
  }

  const dateValue = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(dateValue.getTime())) return "";

  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: CONFIG.timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(dateValue);
  const year = parts.find((part) => part.type === "year")?.value || "";
  const month = parts.find((part) => part.type === "month")?.value || "";
  const day = parts.find((part) => part.type === "day")?.value || "";
  if (!year || !month || !day) return "";
  return `${year}-${month}-${day}`;
}

function addDaysToDateKey(dateKey, daysToAdd) {
  const [year, month, day] = String(dateKey).split("-").map(Number);
  if (!year || !month || !day) return "";
  const date = new Date(Date.UTC(year, month - 1, day));
  date.setUTCDate(date.getUTCDate() + daysToAdd);
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  const d = String(date.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function buildRequiredWeekDates(startDateKey) {
  const dates = [];
  for (let i = 0; i < CONFIG.requiredDailyCount; i += 1) {
    dates.push(addDaysToDateKey(startDateKey, i));
  }
  return dates;
}

function denverDayStartMs(dateKey) {
  const [year, month, day] = String(dateKey).split("-").map(Number);
  if (!year || !month || !day) return NaN;
  const utcNoon = new Date(Date.UTC(year, month - 1, day, 12, 0, 0));
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: CONFIG.timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).formatToParts(utcNoon);
  const byType = Object.fromEntries(parts.map((part) => [part.type, part.value]));
  const denverHour = Number(byType.hour);
  const denverMinute = Number(byType.minute);
  const denverSecond = Number(byType.second);
  const offsetFromUtcNoonMs =
    (denverHour - 12) * 3600000 + denverMinute * 60000 + denverSecond * 1000;
  return utcNoon.getTime() - offsetFromUtcNoonMs;
}

function endOfDenverActivityDayMs(dateKey) {
  const nextKey = addDaysToDateKey(dateKey, 1);
  if (!nextKey) return NaN;
  return denverDayStartMs(nextKey);
}

function resolveGracePeriodHours(value) {
  if (value === null || value === undefined || value === "") {
    return CONFIG.defaultGracePeriodHours;
  }
  const hours = Number(value);
  if (Number.isFinite(hours) && hours >= 0) return hours;
  return CONFIG.defaultGracePeriodHours;
}

function graceDeadlineMs(activityDateKey, gracePeriodHours) {
  return endOfDenverActivityDayMs(activityDateKey) + resolveGracePeriodHours(gracePeriodHours) * 3600000;
}

function classifySubmissionTiming(sub, gracePeriodHours) {
  const activityDateKey = getDateKeyFromDateOnly(
    sub.getCellValue(CONFIG.submissionFields.activityDate)
  );
  const submittedRaw = sub.getCellValue(CONFIG.submissionFields.submittedAt);
  const submittedMs = submittedRaw ? new Date(submittedRaw).getTime() : NaN;
  const manualException = isTruthyFlag(sub, CONFIG.submissionFields.perfectWeekManualException);

  if (manualException) {
    return { activityDateKey, timingStatus: "manual_exception", graceEligible: Boolean(activityDateKey) };
  }
  if (!activityDateKey) {
    return { activityDateKey: "", timingStatus: "ineligible", graceEligible: false };
  }
  if (!Number.isFinite(submittedMs)) {
    return { activityDateKey, timingStatus: "ineligible", graceEligible: false };
  }

  const submittedDateKey = getDateKeyFromDateOnly(submittedRaw);
  if (submittedDateKey === activityDateKey) {
    return { activityDateKey, timingStatus: "on_time", graceEligible: true };
  }

  const deadline = graceDeadlineMs(activityDateKey, gracePeriodHours);
  if (submittedMs <= deadline) {
    return { activityDateKey, timingStatus: "grace_period", graceEligible: true };
  }
  return { activityDateKey, timingStatus: "late", graceEligible: false };
}

function isPerfectWeekQualifyingSubmission(sub, gracePeriodHours) {
  if (!isTruthyNumber(sub, CONFIG.submissionFields.countThisSubmission)) return false;
  if (isTruthyFlag(sub, CONFIG.submissionFields.perfectWeekManualException)) return true;

  if (
    fieldExists(submissionsTable, CONFIG.submissionFields.perfectWeekGraceEligible) &&
    isTruthyNumber(sub, CONFIG.submissionFields.perfectWeekGraceEligible)
  ) {
    return true;
  }

  if (
    fieldExists(submissionsTable, CONFIG.submissionFields.perfectWeekCountable) &&
    isTruthyNumber(sub, CONFIG.submissionFields.perfectWeekCountable)
  ) {
    return true;
  }

  const timing = classifySubmissionTiming(sub, gracePeriodHours);
  if (!timing.graceEligible) return false;
  return getNumber(sub, CONFIG.submissionFields.totalShotsCounted) > 0;
}

function isTruthyNumber(record, fieldName) {
  const value = record.getCellValue(fieldName);
  return value === 1 || value === true || value === "1";
}

function isHomeworkSatisfactory(record) {
  const satisfactory = record.getCellValue(CONFIG.homeworkCompletionFields.satisfactory);
  if (satisfactory === true) return true;

  const status = record.getCellValueAsString(CONFIG.homeworkCompletionFields.completionStatus);
  return status.toLowerCase().includes("satisfactory");
}

async function updateWeekly(fields) {
