function setOutputSafe(name, value) {
  try { output.set(name, value); } catch { /* unmapped outputs are non-fatal */ }
}

function setOutputs(values) {
  for (const [name, value] of Object.entries(values)) setOutputSafe(name, value);
}

function step(name) {
  debugStep = name;
  setOutputSafe("debugStep", name);
}

function field(table, name) {
  try { return table.getField(name); } catch { return null; }
}

function requireField(table, name, writable = false) {
  const found = field(table, name);
  if (!found) throw new Error(`Missing required field: ${table.name} -> ${name}`);
  if (writable && !isWritable(found)) {
    throw new Error(`Required field is not writable: ${table.name} -> ${name}`);
  }
  return found;
}

function isWritable(found) {
  return Boolean(found) && found.isComputed !== true && !new Set([
    "formula", "rollup", "count", "lookup", "multipleLookupValues",
    "createdTime", "lastModifiedTime", "createdBy", "lastModifiedBy",
    "autoNumber", "button", "aiText", "externalSyncSource",
  ]).has(found.type);
}

function raw(record, table, name) {
  return field(table, name) ? record.getCellValue(name) : null;
}

function text(record, table, name) {
  if (!field(table, name)) return "";
  const value = raw(record, table, name);
  if (value === null || value === undefined) return "";
  if (typeof value === "object" && !Array.isArray(value) && value.name) return String(value.name).trim();
  return String(record.getCellValueAsString(name) || "").trim();
}

function number(record, table, name) {
  const value = raw(record, table, name);
  if (typeof value === "number" && Number.isFinite(value)) return value;
  const parsed = Number(String(record?.getCellValueAsString(name) || value || "").replace(/,/g, ""));
  return Number.isFinite(parsed) ? parsed : null;
}

function booleanish(record, table, name) {
  const value = raw(record, table, name);
  if (value === true || value === 1) return true;
  if (value === false || value === 0 || value === null || value === undefined) return false;
  return ["true", "1", "yes", "checked", "active"].includes(String(value).toLowerCase().trim());
}

function checkboxSettled(record, table, name) {
  const value = raw(record, table, name);
  return value !== null && value !== undefined;
}

function numberSettled(record, table, name) {
  const value = raw(record, table, name);
  if (value === null || value === undefined || value === "") return false;
  if (Array.isArray(value) && value.length === 0) return false;
  return true;
}

function ids(record, table, name) {
  const value = raw(record, table, name);
  return Array.isArray(value) ? value.map((item) => item?.id).filter(Boolean) : [];
}

function one(record, table, name) {
  const values = ids(record, table, name);
  return values.length === 1 ? values[0] : "";
}

function linked(id) {
  return id ? [{ id }] : [];
}

function selectValue(table, name, value) {
  const found = field(table, name);
  if (!found) throw new Error(`Missing field: ${table.name} -> ${name}`);
  if (found.type !== "singleSelect") return value;
  const choice = (found.options?.choices || []).find((item) => item.name === value);
  if (!choice) throw new Error(`Missing single-select option "${value}" on ${table.name} -> ${name}`);
  return { id: choice.id };
}

function addWritable(payload, table, name, value) {
  if (value === undefined || value === null || !isWritable(field(table, name))) return;
  payload[name] = value;
}

function dateKeyFromText(textValue) {
  const text = String(textValue || "").trim();
  if (!text) return "";

  const iso = text.match(/^(\d{4}-\d{2}-\d{2})/);
  if (iso) return iso[1];

  const local = text.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})/);
  if (local) {
    return `${local[3]}-${local[1].padStart(2, "0")}-${local[2].padStart(2, "0")}`;
  }

  return "";
}

function dateKeyFromDateObject(value, timeZone = CONFIG.timeZone) {
  if (!value) return "";

  const dateValue = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(dateValue.getTime())) return "";

  // Airtable date-only values are stored as midnight UTC for the entered calendar
  // day. Do not shift that into the previous America/Denver day.
  if (
    dateValue.getUTCHours() === 0 &&
    dateValue.getUTCMinutes() === 0 &&
    dateValue.getUTCSeconds() === 0 &&
    dateValue.getUTCMilliseconds() === 0
  ) {
    const year = dateValue.getUTCFullYear();
    const month = String(dateValue.getUTCMonth() + 1).padStart(2, "0");
    const day = String(dateValue.getUTCDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }

  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(dateValue);

  const year = parts.find((part) => part.type === "year")?.value || "";
  const month = parts.find((part) => part.type === "month")?.value || "";
  const day = parts.find((part) => part.type === "day")?.value || "";
  if (!year || !month || !day) return "";

  return `${year}-${month}-${day}`;
}

function dateKey(value) {
  if (value === null || value === undefined || value === "") return "";

  if (typeof value === "string" || typeof value === "number") {
    return dateKeyFromText(value);
  }

  if (value instanceof Date) {
    return dateKeyFromDateObject(value, CONFIG.timeZone);
  }

  // Airtable may surface date cells as Date-like objects; try text then object.
  const asText = dateKeyFromText(
    typeof value?.toISOString === "function"
      ? value.toISOString()
      : String(value),
  );
  if (asText) return asText;
  return dateKeyFromDateObject(value, CONFIG.timeZone);
}

function todayKey() {
  return dateKeyFromDateObject(new Date(), CONFIG.timeZone);
}

function collectEligibilityFailures({
  enrollment,
  week,
  enrollmentIds,
  weekIds,
  wasCandidates,
  wasIds,
  wasId,
  submission,
  activityDate,
  weekStartKey,
  weekEndKey,
  today,
}) {
  const failures = [];

  if (!enrollmentIds.length) failures.push("missing Enrollment link");
  else if (enrollmentIds.length !== 1) failures.push("ambiguous Enrollment links");
  else if (!enrollment) failures.push("Enrollment record not found");

  if (!weekIds.length) failures.push("missing Week link");
  else if (weekIds.length !== 1) failures.push("ambiguous Week links");
  else if (!week) failures.push("Week record not found");

  if (wasCandidates.length === 0) failures.push("no canonical Weekly Athlete Summary for Enrollment+Week");
  else if (wasCandidates.length !== 1) {
    failures.push(`multiple Weekly Athlete Summary candidates (${wasCandidates.length})`);
  }

  if (wasIds.length > 1) failures.push("ambiguous Submission Weekly Athlete Summary links");
  else if (wasIds.length === 1 && wasId && wasIds[0] !== wasId) {
    failures.push("Submission Weekly Athlete Summary does not match canonical Enrollment+Week summary");
  }

  if (enrollment && !booleanish(enrollment, enrollmentsTable, CONFIG.enrollments.active)) {
    failures.push("Enrollment is not Active?");
  }
  if (!booleanish(submission, submissionsTable, CONFIG.submissions.countThisSubmission)) {
    failures.push("Count This Submission? is false");
  }
  if ((number(submission, submissionsTable, CONFIG.submissions.totalShotsCounted) || 0) <= 0) {
    failures.push("Total Shots Counted is not greater than 0");
  }

  if (!activityDate) failures.push("Activity Date missing or unparseable");
  else {
    if (activityDate > today) {
      failures.push(`Activity Date ${activityDate} is after today ${today} (${CONFIG.timeZone})`);
    }
    if (week) {
      if (!weekStartKey || !weekEndKey) {
        failures.push("Week Start Date or End Date missing or unparseable");
      } else if (activityDate < weekStartKey || activityDate > weekEndKey) {
        failures.push(
          `Activity Date ${activityDate} is outside Week range ${weekStartKey}..${weekEndKey}`,
        );
      }
    }
  }

  if (enrollment && week) {
    const enrollmentPi = one(enrollment, enrollmentsTable, CONFIG.enrollments.programInstance);
    const weekPi = one(week, weeksTable, CONFIG.weeks.programInstance);
    if (!enrollmentPi) failures.push("Enrollment missing Program Instance");
    else if (weekPi !== enrollmentPi) {
      failures.push("Week Program Instance does not match Enrollment Program Instance");
    }
  }

  return failures;
}

function collectNotReadyReasons({
  enrollmentIds,
  weekIds,
  wasCandidates,
  submission,
}) {
  const reasons = [];

  if (!enrollmentIds.length) reasons.push("Enrollment");
  if (!weekIds.length) reasons.push("Week");
  if (
    enrollmentIds.length === 1
    && weekIds.length === 1
    && wasCandidates.length === 0
  ) {
    reasons.push("Weekly Athlete Summary");
  }
  if (!checkboxSettled(submission, submissionsTable, CONFIG.submissions.countThisSubmission)) {
    reasons.push("Count This Submission?");
  }
  if (!numberSettled(submission, submissionsTable, CONFIG.submissions.totalShotsCounted)) {
    reasons.push("Total Shots Counted");
  }

  return reasons;
}

