  lastUpdated: "2026-08-06",
  timeZone: "America/Denver",
  schmidtEnrollmentId: "recCyFEPeATOVNlr9",
  schmidtEnrollmentIds: ["recCyFEPeATOVNlr9", "recgP9qZYjAhE7NXm"],

  tables: {
